package engine

import (
	"strings"
	"testing"

	"github.com/TerracodeBA/vx/internal/merge"
)

const pbHeader = "// Code generated by protoc-gen-go. DO NOT EDIT.\n\npackage v1\n\n"

func genRule(path string) (string, bool) {
	if strings.HasPrefix(path, "gen/") {
		return "buf generate", true
	}
	return "", false
}

// Generated files both sides changed are never text-merged: ours wins
// (even where the text would merge cleanly) and the path is reported.
func TestMergeGeneratedKeepsOurs(t *testing.T) {
	f := newFixture(t)
	base := map[string]string{
		"gen/a.txt":        "1\n2\n3\n",
		"gen/b.txt":        "b\n",
		"gen/c.txt":        "c\n",
		"gen/gone.txt":     "g\n",
		"x_string.go":      pbHeader + "var A = 1\n",
		"api.proto":        "a\nb\nc\n",
		"only_theirs.go":   pbHeader + "var X = 1\n",
		"gen/same.txt":     "s\n",
		"gen/onlyours.txt": "o\n",
	}
	ours := map[string]string{
		"gen/a.txt":        "1 ours\n2\n3\n", // would merge cleanly with theirs
		"gen/b.txt":        "b ours\n",
		"gen/gone.txt":     "g ours\n", // theirs deleted it
		"x_string.go":      pbHeader + "var A = 2\n",
		"api.proto":        "a2\nb\nc\n",
		"only_theirs.go":   pbHeader + "var X = 1\n",
		"gen/same.txt":     "s2\n",
		"gen/onlyours.txt": "o2\n",
		"gen/new.txt":      "new ours\n", // both added
	}
	theirs := map[string]string{
		"gen/a.txt":        "1\n2\n3 theirs\n",
		"gen/b.txt":        "b theirs\n",
		"gen/c.txt":        "c theirs\n", // ours deleted it
		"x_string.go":      pbHeader + "var A = 3\n",
		"api.proto":        "a\nb\nc2\n",
		"only_theirs.go":   pbHeader + "var X = 2\n",
		"gen/same.txt":     "s2\n",
		"gen/onlyours.txt": "o\n",
		"gen/new.txt":      "new theirs\n",
	}
	for _, keep := range []bool{false, true} {
		var r MergeResult
		var err error
		b, o, th := f.tree(base), f.tree(ours), f.tree(theirs)
		labels := merge.Labels{Base: "base", Ours: "ours", Theirs: "theirs"}
		if keep {
			r, err = MergeTreesKeepConflicts(f.ctx, f.s, b, o, th, labels, WithGenerated(genRule))
		} else {
			r, err = MergeTrees(f.ctx, f.s, b, o, th, labels, WithGenerated(genRule))
		}
		if err != nil {
			t.Fatal(err)
		}
		if !r.Clean() {
			t.Fatalf("keep=%v conflicts: %+v", keep, r.Conflicts)
		}
		eq(t, f.read(r.Tree), map[string]string{
			"gen/a.txt":        "1 ours\n2\n3\n",
			"gen/b.txt":        "b ours\n",
			"gen/gone.txt":     "g ours\n",
			"x_string.go":      pbHeader + "var A = 2\n",
			"api.proto":        "a2\nb\nc2\n",
			"only_theirs.go":   pbHeader + "var X = 2\n",
			"gen/same.txt":     "s2\n",
			"gen/onlyours.txt": "o2\n",
			"gen/new.txt":      "new ours\n",
		})
		var got []string
		for _, w := range GeneratedWarnings(r.Generated) {
			got = append(got, w.Detail)
		}
		want := []string{
			"generated file gen/a.txt: regenerate with `buf generate`",
			"generated file gen/b.txt: regenerate with `buf generate`",
			"generated file gen/c.txt: regenerate with `buf generate`",
			"generated file gen/gone.txt: regenerate with `buf generate`",
			"generated file gen/new.txt: regenerate with `buf generate`",
			"generated file x_string.go: regenerate it (both sides changed it; vx kept one side instead of merging the text)",
		}
		if strings.Join(got, "\n") != strings.Join(want, "\n") {
			t.Fatalf("keep=%v warnings:\n%s", keep, strings.Join(got, "\n"))
		}
		if len(r.AutoMerged) != 1 || r.AutoMerged[0] != "api.proto" {
			t.Fatalf("auto-merged: %v", r.AutoMerged)
		}
	}
}

// Without a rule, only files that say they are generated are left alone;
// a rule-less gen/ file conflicts as before.
func TestMergeGeneratedWithoutRules(t *testing.T) {
	f := newFixture(t)
	base := map[string]string{"gen/b.txt": "b\n", "y.pb.go": pbHeader + "var A = 1\n"}
	ours := map[string]string{"gen/b.txt": "b ours\n", "y.pb.go": pbHeader + "var A = 2\n"}
	theirs := map[string]string{"gen/b.txt": "b theirs\n", "y.pb.go": pbHeader + "var A = 3\n"}
	r := f.merge(base, ours, theirs)
	if len(r.Conflicts) != 1 || r.Conflicts[0].Path != "gen/b.txt" {
		t.Fatalf("conflicts: %+v", r.Conflicts)
	}
	if len(r.Generated) != 1 || r.Generated[0].Path != "y.pb.go" || r.Generated[0].Command != "" {
		t.Fatalf("generated: %+v", r.Generated)
	}
}
